mapper.select:
/* com.biz.framework.mapper.pages.SettlementstatusMapper.findSettlementstatus */ SELECT * FROM ( SELECT SM.PAY_YM , SE01.CODE_NAME AS REQ_GUBUN_NAME , IFNULL(SM.FINAL_AMT, SM.CONFIRM_RATE_AMT) AS CONFIRM_RATE_AMT , SR.SETTLEMENT_SEQ , PD.PROD_NAME , C.CUST_NAME , SR.REQ_GUBUN FROM SETTLEMENTMST SM JOIN V_REQ_VIEW SR ON SR.CO_CODE = SM.CO_CODE AND SR.SETTLEMENT_SEQ = SM.SETTLEMENT_SEQ LEFT JOIN CDBASE SE01 ON SE01.CO_CODE = SR.CO_CODE AND SE01.PATTERN_CODE = 'SE01' AND SE01.BASE_CODE = SR.REQ_GUBUN LEFT JOIN TB_PRODUCTS PD ON PD.CO_CODE = SR.CO_CODE AND PD.PROD_ID = SR.PROD_ID LEFT JOIN TB_CUSTOMER C ON C.CO_CODE = SR.CO_CODE AND C.BIZ_NO = SR.CUST_ID WHERE SM.CO_CODE = #{loginCoId} AND SM.USER_ID = #{loginUserId} AND SM.PAY_YM BETWEEN DATE_FORMAT(STR_TO_DATE(#{searchPayYmStart}, '%Y-%m'), '%Y%m') AND DATE_FORMAT(STR_TO_DATE(#{searchPayYmEnd}, '%Y-%m'), '%Y%m')
UNION
SELECT PE.PAY_YM, PE.PAY_NAME AS REQ_GUBUN_NAME, PE.PAY_AMT AS CONFIRM_RATE_AMT, '' AS SETTLEMENT_SEQ, '' AS PROD_NAME, '' AS CUST_NAME, '' AS REQ_GUBUN FROM PAYMENTETC PE WHERE PE.CO_CODE = #{loginCoId} AND PE. USER_ID = #{loginUserId} AND PE.PAY_YM BETWEEN DATE_FORMAT(STR_TO_DATE(#{searchPayYmStart}, '%Y-%m'),'%Y%m') AND DATE_FORMAT(STR_TO_DATE(#{searchPayYmEnd}, '%Y-%m'), '%Y%m') ) AS PAY WHERE 1 = 1
AND PAY.REQ_GUBUN = #{searchReqGubun}

/* com.biz.framework.mapper.pages.SettlementstatusMapper.findSettlementstatusInfo */ SELECT S_SUM.CONFIRM_RATE_AMT_AQ, S_SUM.CONFIRM_RATE_AMT_RQ, ROUND(IFNULL((S_SUM.CONFIRM_RATE_AMT_AQ + S_SUM.CONFIRM_RATE_AMT_RQ), 0) + IFNULL(PE_SUM.PAY_AMT_SUM, 0),0) AS CONFIRM_RATE_AMT_TOT FROM ( SELECT IFNULL(SUM(CASE WHEN S2.REQ_GUBUN IN ('AQ', 'CVQ') THEN IFNULL(S.FINAL_AMT, S.CONFIRM_RATE_AMT) ELSE 0 END), 0) AS CONFIRM_RATE_AMT_AQ , IFNULL(SUM(CASE WHEN S2.REQ_GUBUN = 'RQ' THEN IFNULL(S.FINAL_AMT, S.CONFIRM_RATE_AMT) ELSE 0 END), 0) AS CONFIRM_RATE_AMT_RQ FROM SETTLEMENTMST S JOIN V_REQ_VIEW S2 ON S2.CO_CODE = S.CO_CODE AND S2.SETTLEMENT_SEQ = S.SETTLEMENT_SEQ WHERE S.CO_CODE = #{loginCoId} AND S.USER_ID = #{loginUserId} AND S.PAY_YM BETWEEN DATE_FORMAT(STR_TO_DATE(#{searchPayYmStart}, '%Y-%m'), '%Y%m') AND DATE_FORMAT(STR_TO_DATE(#{searchPayYmEnd}, '%Y-%m'), '%Y%m')
AND S2.REQ_GUBUN = #{searchReqGubun}
) AS S_SUM CROSS JOIN ( SELECT CAST(IFNULL(SUM(PE.PAY_AMT), 0) AS SIGNED) AS PAY_AMT_SUM FROM PAYMENTETC PE WHERE PE.CO_CODE = #{loginCoId} AND PE.USER_ID = #{loginUserId} AND PE.PAY_YM BETWEEN DATE_FORMAT(STR_TO_DATE(#{searchPayYmStart}, '%Y-%m'), '%Y%m') AND DATE_FORMAT(STR_TO_DATE(#{searchPayYmEnd}, '%Y-%m'), '%Y%m') ) AS PE_SUM
